from datetime import date; from decimal import Decimal; from uuid import uuid4; from src.advisor.orm.chat import ChatMessage, ChatMessageRole, ChatSession, ChatSessionStatus; from src.pricing.orm.market_data import FxRate
def test_chat_session_repr(): 'AC6.4.1'; session = ChatSession(id=uuid4(), user_id=uuid4(), title='Test Session', status=ChatSessionStatus.ACTIVE); repr_str = repr(session); assert 'ChatSession' in repr_str; assert 'status=active' in repr_str; 'AC6.4.1'; 'AC6.4.1'; _m1_session_id = uuid4(); _m1_message = ChatMessage(id=uuid4(), session_id=_m1_session_id, role=ChatMessageRole.USER, content='Hello'); _m1_repr_str = repr(_m1_message); assert 'ChatMessage' in _m1_repr_str; assert 'user' in _m1_repr_str; assert str(_m1_session_id) in _m1_repr_str; 'AC6.4.1'; 'AC6.4.1'; assert ChatSession.__table__.c.status.type.enums == ['active', 'deleted']; assert ChatMessage.__table__.c.role.type.enums == ['user', 'assistant', 'system']; _m3_fx_rate = FxRate(base_currency='USD', quote_currency='SGD', rate=Decimal('1.35'), rate_date=date(2024, 1, 1), source='test'); _m3_repr_str = repr(_m3_fx_rate); assert 'FxRate' in _m3_repr_str; assert 'USD/SGD' in _m3_repr_str; assert '1.35' in _m3_repr_str; from src.extraction import BankStatementStatus; from src.extraction.base.validation import route_by_threshold; assert route_by_threshold(85, True) == BankStatementStatus.APPROVED; assert route_by_threshold(60, True) == BankStatementStatus.PARSED; assert route_by_threshold(50, False) == BankStatementStatus.PARSED; assert route_by_threshold(50, True) == BankStatementStatus.UPLOADED; from src.extraction.base.validation import compute_confidence_score; _m5_extracted_data = {'description': 'Test', 'amount': 'not_a_number', 'transaction_date': '2024-01-01'}; _m5_balance_result = {'balance_valid': False, 'difference': 'invalid_decimal'}; _m5_score = compute_confidence_score(_m5_extracted_data, _m5_balance_result); assert isinstance(_m5_score, int); assert 0 <= _m5_score <= 100; from src.ledger import Account, AccountType; _m6_account = Account(id=uuid4(), name='Cash', type=AccountType.ASSET, code='1000', currency='USD', user_id=uuid4()); _m6_result = repr(_m6_account); assert _m6_result == '<Account Cash (ASSET)>'; from src.ledger import JournalEntry, JournalEntryStatus; _m7_entry = JournalEntry(id=uuid4(), user_id=uuid4(), entry_date=date(2024, 1, 15), memo='This is a very long memo that should be truncated in the repr', status=JournalEntryStatus.DRAFT); _m7_result = repr(_m7_entry); assert _m7_result == '<JournalEntry 2024-01-15 - This is a very long memo that >'; from src.ledger import Direction, JournalLine; _m8_line = JournalLine(id=uuid4(), journal_entry_id=uuid4(), account_id=uuid4(), direction=Direction.DEBIT, amount='1000.00', currency='USD'); _m8_result = repr(_m8_line); assert _m8_result == '<JournalLine DEBIT 1000.00 USD>'; from src.extraction import DocumentType, UploadedDocument; _m9_document = UploadedDocument(id=uuid4(), user_id=uuid4(), original_filename='statement.pdf', document_type=DocumentType.BANK_STATEMENT, file_path='uploads/statement.pdf', file_hash='abc123'); _m9_result = repr(_m9_document); assert _m9_result == '<UploadedDocument statement.pdf (bank_statement)>'; from src.extraction import TransactionDirection; from src.extraction.orm.layer2 import AtomicTransaction; _m10_transaction = AtomicTransaction(id=uuid4(), user_id=uuid4(), txn_date=date(2024, 1, 15), direction=TransactionDirection.IN, amount='500.00', currency='SGD', description='Test transaction'); _m10_result = repr(_m10_transaction); assert _m10_result == '<AtomicTransaction 2024-01-15 IN 500.00 SGD>'; from src.extraction.orm.layer2 import AtomicPosition; _m11_position = AtomicPosition(id=uuid4(), user_id=uuid4(), snapshot_date=date(2024, 1, 15), asset_identifier='AAPL', quantity='100', market_value='15000.00', currency='USD'); _m11_result = repr(_m11_position); assert _m11_result == '<AtomicPosition 2024-01-15 AAPL 100 @ 15000.00 USD>'; from src.portfolio import DividendIncome; _m12_dividend = DividendIncome(payment_date=date(2024, 3, 15), amount='125.50', currency='USD'); _m12_result = repr(_m12_dividend); assert _m12_result == '<DividendIncome 2024-03-15 125.50 USD>'; from src.pricing import MarketDataOverride; _m13_override = MarketDataOverride(asset_identifier='AAPL', price='185.50', price_date=date(2024, 3, 15)); _m13_result = repr(_m13_override); assert _m13_result == '<MarketDataOverride AAPL 185.50 on 2024-03-15>'
